@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#concern-table'),action=document.querySelector('#concern-action-form');HRIS.bindForm(document.querySelector('#concern-form'),{success:()=>table.table.load()});HRIS.bindForm(action,{success:()=>table.table.load()});table.addEventListener('table:action',({detail:{action:kind,row}})=>{if(kind==='details')HRIS.showDetails('Concern and action history',row);else{HRIS.fillForm(action,{});action.dataset.endpoint=`/concerns/${row.id}/transition`;HRIS.openModal('concern-action')}})});</script>@endpush
